// Serve committed fixture run files (generated by the real CLI) in place of static/runs/.
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type { Locator, Page } from '@playwright/test';

const FIXTURES = fileURLToPath(new URL('../fixtures/', import.meta.url));

export type FixtureSet = 'runs' | 'runs-empty' | 'runs-malformed';

export async function serveFixtures(
	page: Page,
	set: FixtureSet = 'runs',
	gate?: Promise<void>
): Promise<void> {
	await page.route('**/runs/*.json', async (route) => {
		const file = new URL(route.request().url()).pathname.split('/').pop() ?? '';
		if (gate && file === 'index.json') await gate;
		const path = `${FIXTURES}${set}/${file}`;
		if (existsSync(path)) {
			await route.fulfill({ path, contentType: 'application/json' });
		} else {
			await route.fulfill({ status: 404, body: 'Not found' });
		}
	});
}

export async function openDashboard(page: Page, set: FixtureSet = 'runs'): Promise<void> {
	await serveFixtures(page, set);
	await page.goto('/');
}

/** Job ids of the visible table rows, top to bottom. */
export async function rowIds(table: Locator): Promise<string[]> {
	const ids = await table
		.locator('tbody tr[data-job-id]')
		.evaluateAll((rows) => rows.map((r) => r.getAttribute('data-job-id') ?? ''));
	return ids;
}

